test('lateFee calculates 0.04% per day for one day overdue', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
    terms: 'NET30',
  });

  const r2 = issueInvoice(r1.value, []);
  const totals = invoiceTotals(r2.value).total;
  const result = lateFee(r2.value, '2026-11-07');

  // 0.04% of total per day = (total * 0.04 / 100) * 1
  const expected = Math.round(totals * 0.04 / 100);
  assert.equal(result, expected);
});

